dspy.clients.utils_finetune.validate_dat.source_code:
def validate_data_format(
    data: list[dict[str, Any]],
    data_format: TrainDataFormat,
):
    find_err_funcs = {
        TrainDataFormat.CHAT: find_data_error_chat,
        TrainDataFormat.COMPLETION: find_data_errors_completion,
    }
    err = f"Data format {data_format} is not supported."
    assert data_format in find_err_funcs, err
    find_err_func = find_err_funcs[data_format]

    if not isinstance(data, list):
        err = f"Data is not a list. Found data type: {type(data)}"
        raise ValueError(err)

    data_dict_errors = []
    for ind, data_dict in enumerate(data):
        err = f"Not a dictionary -- found data type: {type(data_dict)}"
        if isinstance(data_dict, dict):
            err = find_err_func(data_dict)
        if err:
            err_dict = {"index": ind, "error": err}
            data_dict_errors.append(err_dict)

    if data_dict_errors:
        finetune_dir = get_finetune_directory()
        log_path = os.path.join(finetune_dir, "data_format_errors.log")
        log_path = os.path.abspath(log_path)
        write_lines(log_path, data_dict_errors)

        err = f"Data format errors found.  For more details, see the log file: {log_path}"
        raise ValueError(err)

dspy.clients.utils_finetune.find_data_er.source_code:
def find_data_errors_completion(data_dict: dict[str, str]) -> str | None:
    keys = ["prompt", "completion"]

    assert isinstance(data_dict, dict)
    expected_keys = sorted(keys)
    found_keys = sorted(data_dict.keys())
    if set(expected_keys) != set(found_keys):
        return f"Expected Keys: {expected_keys}; Found Keys: {found_keys}"

    for key in keys:
        if not isinstance(data_dict[key], str):
            return f"Expected `{key}` to be of type `str`. Found: {type(data_dict[key])}"

def find_data_error_chat(messages: dict[str, Any]) -> str | None:
    assert isinstance(messages, dict)

    expected_keys = ["messages"]
    found_keys = sorted(messages.keys())
    if set(expected_keys) != set(found_keys):
        return f"Expected Keys: {expected_keys}; Found Keys: {found_keys}"

    if not isinstance(messages["messages"], list):
        return f"The value of the `messages` key should be a list instance. Found: {type(messages['messages'])}"

    for ind, message in enumerate(messages["messages"]):
        err = find_data_error_chat_message(message)
        if err:
            return f"Error in message at index {ind}: {err}"

def find_data_error_chat_message(message: dict[str, Any]) -> str | None:
    assert isinstance(message, dict)

    message_keys = sorted(["role", "content"])
    found_keys = sorted(message.keys())
    if set(message_keys) != set(found_keys):
        return f"Expected Keys: {message_keys}; Found Keys: {found_keys}"

    expected_roles = sorted(["assistant", "system", "user"])
    found_role = message["role"]
    if found_role not in expected_roles:
        return f"Expected Roles: {expected_roles}; Found Role: {found_role}"

    if not isinstance(message["content"], str):
        return f"Expected Content Type: `str`; Found Content Type: {type(message['content'])}"

dspy.core.types.LMToolResultPart.source_code:
class LMToolResultPart(LMBasePart):
    """A tool execution result sent back to a model."""

    type: Literal["tool_result"] = "tool_result"
    call_id: str | None = None
    name: str | None = None
    content: list[LMPart] = Field(default_factory=list)
    is_error: bool = False
    provider_data: dict[str, Any] = Field(default_factory=dict)

    @model_validator(mode="before")
    @classmethod
    def normalize_content(cls, data: Any) -> Any:
        if isinstance(data, dict) and "content" in data:
            data = dict(data)
            content = data["content"]
            if content is None:
                data["content"] = []
            elif isinstance(content, list):
                data["content"] = [_coerce_part(item) for item in content]
            else:
                data["content"] = [_coerce_part(content)]
        return data

dspy.core.types.LMCitationPart.source_code:
class LMCitationPart(LMBasePart):
    """A source citation returned by a model."""

    type: Literal["citation"] = "citation"
    text: str | None = None
    title: str | None = None
    url: str | None = None
    metadata: dict[str, Any] = Field(default_factory=dict)

    @model_validator(mode="after")
    def validate_has_content(self) -> LMCitationPart:
        if self.text is None and self.title is None and self.url is None:
            raise ValueError("LMCitationPart requires at least one of text, title, or url.")
        return self

dspy.core.types.LMMessage.source_code:
class LMMessage(BaseModel):
    """A role-attributed sequence of LM parts."""

    role: str
    parts: list[LMPart]
    name: str | None = None
    metadata: dict[str, Any] = Field(default_factory=dict)

    model_config = ConfigDict(extra="forbid")

    @model_validator(mode="before")
    @classmethod
    def normalize_parts(cls, data: Any) -> Any:
        if isinstance(data, cls):
            return data
        if isinstance(data, dict):
            data = dict(data)
            if data.get("role") == "tool" and "parts" not in data:
                content = data.pop("content", None)
                call_id = data.pop("tool_call_id", None)
                name = data.pop("name", None)
                data["parts"] = [
                    LMToolResultPart(
                        call_id=call_id,
                        name=name,
                        content=_parts_from_openai_content(content),
                    )
                ]
            elif "parts" not in data:
                parts = _parts_from_openai_content(data.pop("content", None)) if "content" in data else []
                if "tool_calls" in data:
                    parts.extend(_tool_calls_from_openai(data.pop("tool_calls") or []))
                data["parts"] = parts
            else:
                data["parts"] = [_coerce_part(part) for part in data["parts"]]
                if "tool_calls" in data:
                    data["parts"].extend(_tool_calls_from_openai(data.pop("tool_calls") or []))
        return data

    @property
    def text(self) -> str | None:
        texts = [part.text for part in self.parts if isinstance(part, LMTextPart)]
        return "".join(texts) if texts else None

dspy.core.types.LMReasoningConfig.source_code:
class LMReasoningConfig(BaseModel):
    """Reasoning controls for models with native reasoning support."""

    effort: str | None = None
    max_tokens: int | None = None
    summary: str | None = None

    model_config = ConfigDict(extra="forbid")

    @classmethod
    def from_value(cls, value: Any = None, **overrides: Any) -> LMReasoningConfig:
        data = _config_data(value, str_field="effort")
        if "reasoning_effort" in data and "effort" not in data:
            data["effort"] = data.pop("reasoning_effort")
        data.update({key: value for key, value in overrides.items() if value is not _MISSING})
        return cls(**data)

dspy.core.types.LMToolChoice.source_code:
class LMToolChoice(BaseModel):
    """Tool-choice controls for native tool-capable models."""

    mode: Literal["auto", "required", "none"] = "auto"
    # Tool names that are allowed for a model request.
    allowed: list[str] | None = None
    parallel: bool | None = None

    model_config = ConfigDict(extra="forbid")

    @classmethod
    def from_value(cls, value: Any = None, **overrides: Any) -> LMToolChoice:
        if isinstance(value, Mapping) and value.get("type") == "function" and isinstance(value.get("function"), Mapping):
            # Accept OpenAI/LiteLLM-shaped tool choices for the current BaseLM
            # compatibility path. Internally, DSPy represents this as requiring
            # one allowed tool.
            data = {"mode": "required", "allowed": [value["function"].get("name", "")]}
        else:
            data = _config_data(value, str_field="mode")
        if "parallel_tool_calls" in data and "parallel" not in data:
            data["parallel"] = data.pop("parallel_tool_calls")
        data.update({key: value for key, value in overrides.items() if value is not _MISSING})
        return cls(**data)

