class LMOutputBuilder:
    """Assemble streamed LM events into a final `LMResponse`."""

    def __init__(self):
        self.model: str | None = None
        self._parts: dict[int, list[LMPart | None]] = {}
        self._finish_reasons: dict[int, str | None] = {}
        self._truncated: dict[int, bool] = {}

    def apply(self, event: LMStreamEvent) -> LMResponse | None:
        if isinstance(event, LMStreamStartEvent):
            self.model = event.model
            return None
        if isinstance(event, LMStreamDeltaEvent):
            self._apply_delta(event)
            return None
        if isinstance(event, LMStreamOutputEndEvent):
            self._finish_reasons[event.output_index] = event.finish_reason
            self._truncated[event.output_index] = event.truncated
            return None
        if isinstance(event, LMStreamEndEvent):
            if event.response is not None:
                return event.response
            return self.to_response(usage=event.usage, cost=event.cost)
        if isinstance(event, LMStreamErrorEvent):
            raise event.error
        return None

    def to_response(self, *, usage: LMUsage | dict[str, Any] | None = None, cost: float | None = None) -> LMResponse:
        output_indices = set(self._parts) | set(self._finish_reasons) | set(self._truncated)
        if not output_indices:
            output_indices = {0}
        max_index = max(output_indices)
        expected_indices = set(range(max_index + 1))
        if output_indices != expected_indices:
            missing = sorted(expected_indices - output_indices)
            raise ValueError(f"Stream output indices must be contiguous from 0; missing indices: {missing}.")

        outputs = []
        for output_index in range(max_index + 1):
            part_buffer = self._parts.get(output_index, [])
            missing_part_indices = [index for index, part in enumerate(part_buffer) if part is None]
            if missing_part_indices:
                raise ValueError(
                    f"Stream part indices for output {output_index} must be contiguous; "
                    f"missing indices: {missing_part_indices}."
                )
            parts = [_finalize_stream_part(part) for part in part_buffer]
            outputs.append(
                LMOutput(
                    parts=parts,
                    finish_reason=self._finish_reasons.get(output_index),
                    truncated=self._truncated.get(output_index, False),
                )
            )
        return LMResponse(model=self.model, outputs=outputs, usage=usage, cost=cost)

    def _apply_delta(self, event: LMStreamDeltaEvent) -> None:
        parts = self._parts.setdefault(event.output_index, [])
        while len(parts) <= event.part_index:
            parts.append(None)

        current = parts[event.part_index]
        delta = event.delta
        if isinstance(delta, LMThinkingDelta):
            if current is not None and not isinstance(current, LMThinkingPart):
                raise ValueError("Cannot apply thinking delta to a non-thinking stream part.")
            text = (current.text if isinstance(current, LMThinkingPart) else "") + delta.text
            parts[event.part_index] = LMThinkingPart(text=text)
        elif isinstance(delta, LMTextDelta):
            if current is not None and not isinstance(current, LMTextPart):
                raise ValueError("Cannot apply text delta to a non-text stream part.")
            text = (current.text if isinstance(current, LMTextPart) else "") + delta.text
            parts[event.part_index] = LMTextPart(text=text)
        elif isinstance(delta, LMToolCallDelta):
            if current is not None and not isinstance(current, LMToolCallPart):
                raise ValueError("Cannot apply tool-call delta to a non-tool-call stream part.")
            buffer = ""
            if isinstance(current, LMToolCallPart):
                buffer = current.provider_data.get("args_buffer", "")
            buffer += delta.args_delta or ""
            args = _parse_json_object(buffer)
            parts[event.part_index] = LMToolCallPart(
                id=delta.id if delta.id is not None else getattr(current, "id", None),
                name=delta.name if delta.name is not None else getattr(current, "name", ""),
                args=args,
                provider_data={"args_buffer": buffer},
            )
        elif isinstance(delta, LMCitationDelta):
            if current is not None and not isinstance(current, LMCitationPart):
                raise ValueError("Cannot apply citation delta to a different stream part type.")
            parts[event.part_index] = delta.citation
        elif isinstance(delta, LMImageDelta):
            if current is not None and not isinstance(current, LMImagePart):
                raise ValueError("Cannot apply image delta to a different stream part type.")
            parts[event.part_index] = delta.image
        elif isinstance(delta, LMAudioDelta):
            if current is not None and not isinstance(current, LMAudioPart):
                raise ValueError("Cannot apply audio delta to a different stream part type.")
            parts[event.part_index] = delta.audio

dspy.core.types.LMStream.source_code:
class LMStream:
    """Synchronous LM stream with a final `LMResponse` result."""

    def __init__(
        self,
        *,
        request: LMRequest,
        events: Iterator[LMStreamEvent],
        finalize: Callable[[LMRequest, LMResponse], LMResponse],
    ):
        self.request = request
        self._events = events
        self._finalize = finalize
        self._builder = LMOutputBuilder()
        self._result: LMResponse | None = None

    def __iter__(self) -> Iterator[LMStreamEvent]:
        for event in self._events:
            response = self._builder.apply(event)
            if response is not None:
                self._result = self._finalize(self.request, response)
            yield event

    def result(self) -> LMResponse:
        if self._result is None:
            raise RuntimeError("Stream has not completed yet.")
        return self._result

dspy.core.types._history_request_prompt.source_code:
def _history_request_prompt(request: LMRequest) -> str | None:
    if len(request.messages) != 1:
        return None
    message = request.messages[0]
    if message.role != "user" or len(message.parts) != 1:
        return None
    part = message.parts[0]
    return part.text if isinstance(part, LMTextPart) else None

dspy.core.types._history_request_message.source_code:
def _history_request_messages_as_openai(request: LMRequest) -> list[dict[str, Any]]:
    messages = []
    for message in request.messages:
        if message.role == "assistant":
            tool_calls = [part for part in message.parts if isinstance(part, LMToolCallPart)]
            content_parts = [part for part in message.parts if not isinstance(part, LMToolCallPart)]
            item: dict[str, Any] = {
                "role": "assistant",
                "content": _history_message_parts_as_openai_content(content_parts) if content_parts else None,
            }
            if tool_calls:
                item["tool_calls"] = [_history_tool_call_as_openai(call) for call in tool_calls]
        elif message.role == "tool" and len(message.parts) == 1 and isinstance(message.parts[0], LMToolResultPart):
            result = message.parts[0]
            item = {"role": "tool", "content": _history_tool_result_content(result)}
            if result.call_id is not None:
                item["tool_call_id"] = result.call_id
            if result.name is not None:
                item["name"] = result.name
        else:
            item = {
                "role": message.role,
                "content": _history_message_parts_as_openai_content(message.parts),
            }
        if message.name is not None and "name" not in item:
            item["name"] = message.name
        messages.append(item)
    return messages

dspy.core.types._history_tool_call_as_op.source_code:
def _history_tool_call_as_openai(call: LMToolCallPart) -> dict[str, Any]:
    data: dict[str, Any] = {
        "type": "function",
        "function": {
            "name": call.name,
            "arguments": json.dumps(call.args),
        },
    }
    if call.id is not None:
        data["id"] = call.id
    return data

dspy.core.types._history_tool_result_con.source_code:
def _history_tool_result_content(result: LMToolResultPart) -> str:
    chunks = []
    for part in result.content:
        if isinstance(part, LMTextPart):
            chunks.append(part.text)
        else:
            chunks.append(json.dumps(part.model_dump(mode="json", exclude_none=True), ensure_ascii=False))
    return "".join(chunks)

dspy.core.types._history_message_parts_a.source_code:
def _history_message_parts_as_openai_content(parts: list[LMPart]) -> str | list[dict[str, Any]]:
    if len(parts) == 1 and isinstance(parts[0], LMTextPart):
        return parts[0].text
    return [_history_part_as_openai_content(part) for part in parts]

dspy.core.types._history_part_as_openai_.source_code:
def _history_part_as_openai_content(part: LMPart) -> dict[str, Any]:
    if isinstance(part, LMTextPart):
        return {"type": "text", "text": part.text}
    if isinstance(part, LMImagePart):
        return {"type": "image_url", "image_url": {"url": _history_part_source(part)}}
    if isinstance(part, LMAudioPart):
        input_audio = {"format": _history_media_format(part.media_type)}
        if part.data is not None:
            if part.data.startswith("data:"):
                media_type, data = _split_data_uri(part.data)
                input_audio["format"] = _history_media_format(media_type)
                input_audio["data"] = data
            else:
                input_audio["data"] = part.data
        elif part.url is not None:
            input_audio["url"] = part.url
        elif part.file_id is not None:
            input_audio["file_id"] = part.file_id
        elif part.path is not None:
            input_audio["path"] = part.path
        return {
            "type": "input_audio",
            "input_audio": input_audio,
        }
    if isinstance(part, LMVideoPart):
        video = {"media_type": part.media_type}
        if part.data is not None:
            video["data"] = _history_part_source(part)
        elif part.url is not None:
            video["url"] = part.url
        elif part.file_id is not None:
            video["file_id"] = part.file_id
        elif part.path is not None:
            video["path"] = part.path
        return {"type": "video", "video": video}
    if isinstance(part, LMDocumentPart):
        data = {"type": "document"}
        if part.source is not None:
            data["source"] = part.source
        else:
            data["source"] = _history_part_source(part)
            data["media_type"] = part.media_type
        if part.citations:
            data["citations"] = part.citations
        if part.title is not None:
            data["title"] = part.title
        if part.context is not None:
            data["context"] = part.context
        return data
    if isinstance(part, LMBinaryPart):
        return {
            "type": "binary",
            "binary": {
                key: value
                for key, value in {
                    "data": _history_part_source(part),
                    "file_id": part.file_id,
                    "filename": part.filename,
                    "media_type": part.media_type,
                }.items()
                if value is not None
            },
        }
    return part.model_dump(exclude_none=True)

dspy.core.types._history_part_source.source_code:
def _history_part_source(part: LMImagePart | LMAudioPart | LMVideoPart | LMDocumentPart | LMBinaryPart) -> str | None:
    if part.data is not None:
        return part.data if part.data.startswith("data:") else f"data:{part.media_type};base64,{part.data}"
    return part.url or part.file_id or part.path

dspy.core.types._history_request_kwargs.source_code:
def _history_request_kwargs(request: LMRequest) -> dict[str, Any]:
    data = request.config.model_dump(exclude_none=True)
    extensions = data.pop("extensions", {}) or {}
    return {**extensions, **data}

dspy.core.types._validate_one_source.source_code:
def _validate_one_source(part: Any) -> None:
    sources = {name: getattr(part, name) for name in ("data", "url", "file_id", "path") if getattr(part, name) is not None}
    class_name = type(part).__name__
    if len(sources) != 1:
        raise ValueError(f"{class_name} requires exactly one of data, url, file_id, or path.")
    name, value = next(iter(sources.items()))
    if isinstance(value, str) and not value:
        raise ValueError(f"{class_name}.{name} must be non-empty.")

dspy.core.types._coerce_message.source_code:
def _coerce_message(value: dict[str, Any] | LMMessage) -> LMMessage:
    if isinstance(value, LMMessage):
        return value
    return LMMessage(**value)

dspy.core.types._messages_from_items.source_code:
def _messages_from_items(items: tuple[Any, ...], *, prompt: str | None = None) -> tuple[list[LMMessage], list[Any]]:
    # TODO: Normalize DSPy-specific LM(...) objects in the LM call layer before building LMRequest.
    if prompt is not None:
        items = (prompt, *items)
    if not items:
        items = ("",)

    if len(items) == 1 and _is_message_sequence(items[0]):
        items = tuple(items[0])

    if all(isinstance(item, LMMessage) or isinstance(item, LMResponse) for item in items):
        messages: list[LMMessage] = []
        for item in items:
            if isinstance(item, LMMessage):
                messages.append(item)
            else:
                messages.extend(_messages_from_response(item))
        return messages, []

    parts = [_coerce_part(item) for item in items]
    return [LMMessage(role="user", parts=parts)], []

dspy.core.types._is_message_sequence.source_code:
def _is_message_sequence(value: Any) -> bool:
    return isinstance(value, (list, tuple)) and all(
        isinstance(item, LMMessage) or isinstance(item, LMResponse) for item in value
    )

dspy.core.types._coerce_part.source_code:
def _coerce_part(value: Any) -> LMPart:
    if isinstance(
        value,
        (
            LMTextPart,
            LMImagePart,
            LMAudioPart,
            LMVideoPart,
            LMDocumentPart,
            LMBinaryPart,
            LMToolCallPart,
            LMToolResultPart,
            LMThinkingPart,
            LMCitationPart,
            LMRefusalPart,
        ),
    ):
        return value
    if isinstance(value, str):
        return LMTextPart(text=value)
    if isinstance(value, dict) and "type" in value:
        return pydantic.TypeAdapter(LMPart).validate_python(value)
    raise TypeError(f"Cannot convert {type(value)!r} to an LMPart.")

dspy.core.types._parts_from_openai_conte.source_code:
def _parts_from_openai_content(content: Any) -> list[LMPart]:
    if content is None:
        return []
    if isinstance(content, str):
        return [LMTextPart(text=content)]
    if not isinstance(content, list):
        return [_coerce_part(content)]

    parts = []
    for item in content:
        item_type = item.get("type") if isinstance(item, dict) else None
        if item_type == "text":
            parts.append(LMTextPart(text=item.get("text", ""), metadata=item.get("metadata", {}) or {}))
        elif item_type == "image_url":
            image = item.get("image_url", {})
            if not isinstance(image, dict):
                raise TypeError("Image content block must be a mapping.")
            url = image.get("url")
            if url is None:
                raise ValueError("Image content block requires url.")
            parts.append(_image_source_to_part(url))
        elif item_type == "input_audio":
            audio = item.get("input_audio", {})
            parts.append(_audio_dict_to_part(audio))
        elif item_type == "file":
            parts.append(_binary_dict_to_part(item.get("file", {})))
        elif item_type == "document":
            parts.append(_document_dict_to_part(item))
        elif item_type == "video":
            video = item.get("video", {})
            parts.append(_media_dict_to_video_part(video))
        else:
            parts.append(_coerce_part(item))
    return parts

dspy.core.types._tool_call_from_openai.source_code:
def _tool_call_from_openai(tool_call: Any) -> LMToolCallPart:
    if not isinstance(tool_call, Mapping):
        part = _coerce_part(tool_call)
        if isinstance(part, LMToolCallPart):
            return part
        raise TypeError(f"Cannot convert {type(tool_call)!r} to an LMToolCallPart.")

    function = tool_call.get("function", {})
    if not isinstance(function, Mapping):
        function = {}

    args = function.get("arguments", {})
    if isinstance(args, str):
        args = _parse_json_object(args)
    elif isinstance(args, Mapping):
        args = dict(args)
    else:
        args = {}

    return LMToolCallPart(
        id=tool_call.get("id"),
        name=function.get("name") or tool_call.get("name") or "",
        args=args,
    )

dspy.core.types._image_source_to_part.source_code:
def _image_source_to_part(source: str) -> LMImagePart:
    if not isinstance(source, str):
        raise TypeError("Image URL must be a string.")
    if source.startswith("data:"):
        media_type, data = _split_data_uri(source)
        return LMImagePart(data=data, media_type=media_type)
    media_type = mimetypes.guess_type(urlparse(source).path)[0] or "image/png"
    return LMImagePart(url=source, media_type=media_type)

dspy.core.types._audio_dict_to_part.source_code:
def _audio_dict_to_part(audio: dict[str, Any]) -> LMAudioPart:
    if not isinstance(audio, dict):
        raise TypeError("Audio content block must be a mapping.")

    audio_format = audio.get("format") or "wav"
    if not isinstance(audio_format, str):
        raise TypeError("Audio format must be a string.")
    media_type = audio_format if "/" in audio_format else f"audio/{audio_format}"

    if audio.get("data") is not None:
        data = audio["data"]
        if isinstance(data, str) and data.startswith("data:"):
            media_type, data = _split_data_uri(data)
        return LMAudioPart(data=data, media_type=media_type)
    if audio.get("url") is not None:
        return LMAudioPart(url=audio["url"], media_type=media_type)
    if audio.get("file_id") is not None:
        return LMAudioPart(file_id=audio["file_id"], media_type=media_type)
    if audio.get("path") is not None:
        return LMAudioPart(path=audio["path"], media_type=media_type)
    raise ValueError("Audio content block requires data, url, file_id, or path.")

dspy.core.types._binary_dict_to_part.source_code:
def _binary_dict_to_part(file: dict[str, Any]) -> LMBinaryPart:
    if file.get("file_data") is not None:
        media_type, data = _split_data_uri(file["file_data"])
        return LMBinaryPart(data=data, media_type=media_type, filename=file.get("filename"))
    if file.get("data") is not None:
        media_type, data = _split_data_uri(file["data"])
        return LMBinaryPart(data=data, media_type=media_type, filename=file.get("filename"))
    if file.get("file_id") is not None:
        return LMBinaryPart(file_id=file["file_id"], filename=file.get("filename"))
    raise ValueError("Binary content block requires data, file_data, or file_id.")

dspy.core.types._document_dict_to_part.source_code:
def _document_dict_to_part(item: dict[str, Any]) -> LMDocumentPart:
    common = {"title": item.get("title"), "context": item.get("context")}
    media_type = item.get("media_type") or "application/pdf"
    for source_key in ("data", "url", "file_id", "path"):
        if item.get(source_key) is not None:
            return LMDocumentPart(**{source_key: item[source_key]}, media_type=media_type, **common)

    source = item.get("source")
    if isinstance(source, dict):
        return LMDocumentPart(
            source=source,
            citations=item.get("citations") or {},
            **common,
        )
    if isinstance(source, str):
        kwargs = _media_source_kwargs(source, default_media_type=media_type)
        return LMDocumentPart(**kwargs, **common)
    raise ValueError("Document content block requires source.")

dspy.core.types._media_dict_to_video_par.source_code:
def _media_dict_to_video_part(video: dict[str, Any]) -> LMVideoPart:
    if video.get("data") is not None:
        data = video["data"]
        if isinstance(data, str) and data.startswith("data:"):
            media_type, data = _split_data_uri(data)
        else:
            media_type = video.get("media_type") or "video/mp4"
        return LMVideoPart(data=data, media_type=media_type)
    if video.get("url") is not None:
        return LMVideoPart(url=video["url"], media_type=video.get("media_type") or "video/mp4")
    if video.get("file_id") is not None:
        return LMVideoPart(file_id=video["file_id"], media_type=video.get("media_type") or "video/mp4")
    if video.get("path") is not None:
        return LMVideoPart(path=video["path"], media_type=video.get("media_type") or "video/mp4")
    raise ValueError("Video content block requires data, url, file_id, or path.")

dspy.core.types._split_data_uri.source_code:
def _split_data_uri(value: str) -> tuple[str, str]:
    if not value.startswith("data:") or "," not in value:
        return "application/octet-stream", value
    header, data = value.split(",", 1)
    media_type = header.removeprefix("data:").split(";", 1)[0]
    return media_type, data

dspy.core.types._media_source_kwargs.source_code:
def _media_source_kwargs(source: str, *, default_media_type: str) -> dict[str, str]:
    if source.startswith("data:"):
        media_type, data = _split_data_uri(source)
        return {"data": data, "media_type": media_type}

    parsed = urlparse(source)
    if parsed.scheme in {"http", "https"}:
        media_type = mimetypes.guess_type(parsed.path)[0] or default_media_type
        return {"url": source, "media_type": media_type}

    return {"file_id": source, "media_type": default_media_type}

dspy.core.types._coerce_tool_spec.source_code:
def _coerce_tool_spec(tool: Any) -> LMToolSpec:
    if isinstance(tool, LMToolSpec):
        return tool
    if hasattr(tool, "to_lm_tool_spec"):
        return tool.to_lm_tool_spec()
    if isinstance(tool, dict):
        if "function" in tool:
            function = tool["function"]
            provider_data = {key: value for key, value in tool.items() if key not in {"type", "function"}}
            return LMToolSpec(
                name=function.get("name"),
                description=function.get("description"),
                parameters=function.get("parameters", {}),
                provider_data=provider_data,
            )
        return LMToolSpec(**tool)
    raise TypeError(f"Cannot convert {type(tool)!r} to LMToolSpec.")

dspy.core.types._requires_output_dict.source_code:
def _requires_output_dict(output: LMOutput) -> bool:
    return bool(
        output.logprobs is not None or output.reasoning_content is not None or output.tool_calls or output.citations
    )

dspy.core.types._part_to_value.source_code:
def _part_to_value(part: LMPart) -> Any:
    if isinstance(part, LMTextPart):
        return part.text
    if isinstance(part, LMThinkingPart):
        return part
    if isinstance(part, LMToolCallPart):
        return part
    if isinstance(part, LMRefusalPart):
        return part.text
    return part

dspy.core.types._finalize_stream_part.source_code:
def _finalize_stream_part(part: LMPart) -> LMPart:
    if isinstance(part, LMToolCallPart) and "args_buffer" in part.provider_data:
        return part.model_copy(update={"args": _parse_json_object_strict(part.provider_data["args_buffer"])})
    return part

dspy.core.types._tool_call_to_provider_d.source_code:
def _tool_call_to_provider_dict(call: LMToolCallPart) -> dict[str, Any]:
    data = {
        "type": "function",
        "function": {
            "name": call.name,
            "arguments": json.dumps(call.args),
        },
    }
    if call.id is not None:
        data["id"] = call.id
    return data

dspy.core.types._parse_json_object.source_code:
def _parse_json_object(value: str) -> dict[str, Any]:
    if not value:
        return {}
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        return {}
    return parsed if isinstance(parsed, dict) else {}

dspy.core.types._parse_json_object_stric.source_code:
def _parse_json_object_strict(value: str) -> dict[str, Any]:
    if not value:
        return {}
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError as exc:
        raise ValueError("Streamed tool-call arguments must be a JSON object.") from exc
    if not isinstance(parsed, dict):
        raise ValueError("Streamed tool-call arguments must be a JSON object.")
    return parsed

dspy.datasets.alfworld.alfworld._EnvSess.source_code:
class _EnvSession:
    """
    A context manager that acquires a worker from the pool,
    provides .init(idx) and .step(action), then releases the worker.
    """

    def __init__(self, pool: EnvPool):
        self.pool = pool
        self.wid = None
        self.inq = None
        self.outq = None

    def __enter__(self):
        self.wid, self.inq, self.outq = self.pool._acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.pool._release(self.wid)

    def init(self, idx):
        self.inq.put(("init", idx))
        return self.outq.get()  # (task_def, info)

    def step(self, action):
        self.inq.put(("step", action))
        return self.outq.get()  # (obs, rew, done, info)

dspy.datasets.colors.Colors.source_code:
class Colors(Dataset):
    def __init__(self, sort_by_suffix=True, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)

        self.sort_by_suffix = sort_by_suffix
        colors = self.sorted_by_suffix(all_colors)

        train_size = int(
            len(colors) * 0.6
        )  # chosen to ensure that similar colors aren't repeated between train and dev
        train_colors, dev_colors = colors[:train_size], colors[train_size:]

        self._train = [{"color": color} for color in train_colors]
        self._dev = [{"color": color} for color in dev_colors]

        random.Random(0).shuffle(self._train)
        random.Random(0).shuffle(self._dev)

    def sorted_by_suffix(self, colors):
        if not self.sort_by_suffix:
            return colors

        if isinstance(colors[0], str):
            sorted_colors = sorted(colors, key=lambda x: x[::-1])
        else:
            sorted_colors = sorted(colors, key=lambda x: x["color"][::-1])

        return sorted_colors

dspy.datasets.dataloader.DataLoader.source_code:
class DataLoader(Dataset):
    def __init__(self):
        pass

    def from_huggingface(
        self,
        dataset_name: str,
        *args,
        input_keys: tuple[str] = (),
        fields: tuple[str] | None = None,
        **kwargs,
    ) -> Mapping[str, list[dspy.Example]] | list[dspy.Example]:
        if fields and not isinstance(fields, tuple):
            raise ValueError("Invalid fields provided. Please provide a tuple of fields.")

        if not isinstance(input_keys, tuple):
            raise ValueError("Invalid input keys provided. Please provide a tuple of input keys.")

        from datasets import load_dataset

        dataset = load_dataset(dataset_name, *args, **kwargs)

        if isinstance(dataset, list) and isinstance(kwargs["split"], list):
            dataset = {split_name: dataset[idx] for idx, split_name in enumerate(kwargs["split"])}

        try:
            returned_split = {}
            for split_name in dataset.keys():
                if fields:
                    returned_split[split_name] = [
                        dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys)
                        for row in dataset[split_name]
                    ]
                else:
                    returned_split[split_name] = [
                        dspy.Example({field: row[field] for field in row.keys()}).with_inputs(*input_keys)
                        for row in dataset[split_name]
                    ]

            return returned_split
        except AttributeError:
            if fields:
                return [
                    dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys) for row in dataset
                ]
            else:
                return [
                    dspy.Example({field: row[field] for field in row.keys()}).with_inputs(*input_keys)
                    for row in dataset
                ]

    def from_csv(
        self,
        file_path: str,
        fields: list[str] | None = None,
        input_keys: tuple[str] = (),
    ) -> list[dspy.Example]:
        from datasets import load_dataset

        dataset = load_dataset("csv", data_files=file_path)["train"]

        if not fields:
            fields = list(dataset.features)

        return [dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys) for row in dataset]

    def from_pandas(
        self,
        df: "pd.DataFrame",
        fields: list[str] | None = None,
        input_keys: tuple[str] = (),
    ) -> list[dspy.Example]:
        if fields is None:
            fields = list(df.columns)

        return [
            dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys) for _, row in df.iterrows()
        ]

    def from_json(
        self,
        file_path: str,
        fields: list[str] | None = None,
        input_keys: tuple[str] = (),
    ) -> list[dspy.Example]:
        from datasets import load_dataset

        dataset = load_dataset("json", data_files=file_path)["train"]

        if not fields:
            fields = list(dataset.features)

        return [dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys) for row in dataset]

    def from_parquet(
        self,
        file_path: str,
        fields: list[str] | None = None,
        input_keys: tuple[str] = (),
    ) -> list[dspy.Example]:
        from datasets import load_dataset

        dataset = load_dataset("parquet", data_files=file_path)["train"]

        if not fields:
            fields = list(dataset.features)

        return [dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys) for row in dataset]

    def from_rm(self, num_samples: int, fields: list[str], input_keys: list[str]) -> list[dspy.Example]:
        try:
            rm = dspy.settings.rm
            try:
                return [
                    dspy.Example({field: row[field] for field in fields}).with_inputs(*input_keys)
                    for row in rm.get_objects(num_samples=num_samples, fields=fields)
                ]
            except AttributeError:
                raise ValueError(
                    "Retrieval module does not support `get_objects`. Please use a different retrieval module."
                )
        except AttributeError:
            raise ValueError(
                "Retrieval module not found. Please set a retrieval module using `dspy.configure`."
            )

    def sample(
        self,
        dataset: list[dspy.Example],
        n: int,
        *args,
        **kwargs,
    ) -> list[dspy.Example]:
        if not isinstance(dataset, list):
            raise ValueError(
                f"Invalid dataset provided of type {type(dataset)}. Please provide a list of `dspy.Example`s."
            )

        return random.sample(dataset, n, *args, **kwargs)

    def train_test_split(
        self,
        dataset: list[dspy.Example],
        train_size: int | float = 0.75,
        test_size: int | float | None = None,
        random_state: int | None = None,
    ) -> Mapping[str, list[dspy.Example]]:
        if random_state is not None:
            random.seed(random_state)

        dataset_shuffled = dataset.copy()
        random.shuffle(dataset_shuffled)

        if train_size is not None and isinstance(train_size, float) and (0 < train_size < 1):
            train_end = int(len(dataset_shuffled) * train_size)
        elif train_size is not None and isinstance(train_size, int):
            train_end = train_size
        else:
            raise ValueError(
                "Invalid `train_size`. Please provide a float between 0 and 1 to represent the proportion of the "
                "dataset to include in the train split or an int to represent the absolute number of samples to "
                f"include in the train split. Received `train_size`: {train_size}."
            )

        if test_size is not None:
            if isinstance(test_size, float) and (0 < test_size < 1):
                test_end = int(len(dataset_shuffled) * test_size)
            elif isinstance(test_size, int):
                test_end = test_size
            else:
                raise ValueError(
                    "Invalid `test_size`. Please provide a float between 0 and 1 to represent the proportion of the "
                    "dataset to include in the test split or an int to represent the absolute number of samples to "
                    f"include in the test split. Received `test_size`: {test_size}."
                )
            if train_end + test_end > len(dataset_shuffled):
                raise ValueError(
                    "`train_size` + `test_size` cannot exceed the total number of samples. Received "
                    f"`train_size`: {train_end}, `test_size`: {test_end}, and `dataset_size`: {len(dataset_shuffled)}."
                )
        else:
            test_end = len(dataset_shuffled) - train_end

        train_dataset = dataset_shuffled[:train_end]
        test_dataset = dataset_shuffled[train_end : train_end + test_end]

        return {"train": train_dataset, "test": test_dataset}

dspy.datasets.gsm8k.parse_integer_answer.source_code:
def parse_integer_answer(answer, only_first_line=True):
    try:
        if only_first_line:
            answer = answer.strip().split("\n")[0]

        # find the last token that has a number in it
        answer = [token for token in answer.split() if any(c.isdigit() for c in token)][-1]
        answer = answer.split(".")[0]
        answer = "".join([c for c in answer if c.isdigit()])
        answer = int(answer)

    except (ValueError, IndexError):
        answer = 0

    return answer

