def merge_dicts(d1, d2) -> dict:
    # Convert to dict if objects have toDict method (e.g., Example objects)
    if hasattr(d1, "toDict"):
        d1 = d1.toDict()
    if hasattr(d2, "toDict"):
        d2 = d2.toDict()

    merged = {}
    for k, v in d1.items():
        if k in d2:
            merged[f"example_{k}"] = v
        else:
            merged[k] = v

    for k, v in d2.items():
        if k in d1:
            merged[f"pred_{k}"] = v
        else:
            merged[k] = v

    return merged

