dspy.utils.logging_utils.DSPyLoggingStre.source_code:
class DSPyLoggingStream:
    """
    A Python stream for use with event logging APIs throughout DSPy (`eprint()`,
    `logger.info()`, etc.). This stream wraps `sys.stderr`, forwarding `write()` and
    `flush()` calls to the stream referred to by `sys.stderr` at the time of the call.
    It also provides capabilities for disabling the stream to silence event logs.
    """

    def __init__(self):
        self._enabled = True

    def write(self, text):
        if self._enabled:
            sys.stderr.write(text)

    def flush(self):
        if self._enabled:
            sys.stderr.flush()

    @property
    def enabled(self):
        return self._enabled

    @enabled.setter
    def enabled(self, value):
        self._enabled = value

dspy.utils.magicattr.get.source_code:
def get(obj, attr, **kwargs):
    """A getattr that supports nested lookups on objects, dicts, lists, and
    any combination in between.
    """
    for chunk in _parse(attr):
        try:
            obj = _lookup(obj, chunk)
        except Exception as ex:
            if "default" in kwargs:
                return kwargs["default"]
            else:
                raise ex
    return obj

dspy.utils.magicattr.set.source_code:
def set(obj, attr, val):
    """A setattr that supports nested lookups on objects, dicts, lists, and
    any combination in between.
    """
    obj, attr_or_key, is_subscript = lookup(obj, attr)
    if is_subscript:
        obj[attr_or_key] = val
    else:
        setattr(obj, attr_or_key, val)

dspy.utils.magicattr.delete.source_code:
def delete(obj, attr):
    """A delattr that supports deletion of a nested lookups on objects,
    dicts, lists, and any combination in between.
    """
    obj, attr_or_key, is_subscript = lookup(obj, attr)
    if is_subscript:
        del obj[attr_or_key]
    else:
        delattr(obj, attr_or_key)

dspy.utils.magicattr.lookup.source_code:
def lookup(obj, attr):
    """Like get but instead of returning the final value it returns the
    object and action that will be done.
    """
    nodes = tuple(_parse(attr))
    if len(nodes) > 1:
        obj = reduce(_lookup, nodes[:-1], obj)
        node = nodes[-1]
    else:
        node = nodes[0]
    if isinstance(node, ast.Attribute):
        return obj, node.attr, False
    elif isinstance(node, ast.Subscript):
        return obj, _lookup_subscript_value(node.slice), True
    elif isinstance(node, ast.Name):
        return obj, node.id, False
    raise NotImplementedError("Node is not supported: %s" % node)

